/**
 * Constructs the complete child process environment at the spawn boundary.
 * Never spreads the Supervisor's process.env into an untrusted application.
 */
export interface ChildEnvironmentInput {
  /** Host variables, reduced to an explicit operating-system allowlist. */
  systemEnv?: NodeJS.ProcessEnv;
  /** Per-application deployment configuration (business settings only). */
  applicationEnv?: Readonly<Record<string, string>>;
  /** Trusted Supervisor process specification (PORT, HOST, identity, etc.). */
  runtimeEnv?: Readonly<Record<string, string>>;
  /** Generated by ArmRuntimeInjector and takes final precedence. */
  injectionEnv?: Readonly<Record<string, string>>;
}

const SYSTEM_KEYS = [
  'PATH', 'HOME', 'USER', 'LOGNAME', 'LANG', 'LC_ALL', 'LC_CTYPE',
  'TZ', 'TMPDIR', 'TMP', 'TEMP',
  // Windows process initialization, executable resolution and per-user paths.
  'SystemRoot', 'SYSTEMROOT', 'WINDIR', 'ComSpec', 'COMSPEC', 'PATHEXT',
  'USERPROFILE', 'APPDATA', 'LOCALAPPDATA',
] as const;

const FORBIDDEN_APP_KEYS = new Set([
  'NODE_OPTIONS', 'NODE_PATH', 'NODE_EXTRA_CA_CERTS', 'NODE_REPL_HISTORY',
  'NODE_REDIRECT_WARNINGS', 'NODE_V8_COVERAGE', 'NODE_ICU_DATA',
  'NODE_ENV', 'HOST', 'PORT',
]);

const ENV_KEY = /^[A-Za-z_][A-Za-z0-9_]*$/;

function validateEntry(key: string, value: string, source: string): void {
  if (!ENV_KEY.test(key) || typeof value !== 'string' || value.includes('\0')) {
    throw new Error(`Invalid ${source} environment entry: ${key}`);
  }
}

function assertAllowedApplicationKey(key: string): void {
  const normalized = key.toUpperCase();
  if (normalized.startsWith('ARM_') || normalized.startsWith('SUPERVISOR_') ||
      FORBIDDEN_APP_KEYS.has(normalized)) {
    throw new Error(`Reserved application environment variable: ${key}`);
  }
}

export class ChildEnvironmentBuilder {
  constructor(private readonly systemEnv: NodeJS.ProcessEnv = process.env) {}

  build(input: Omit<ChildEnvironmentInput, 'systemEnv'> & {
    systemEnv?: NodeJS.ProcessEnv;
  } = {}): NodeJS.ProcessEnv {
    const result: NodeJS.ProcessEnv = {};
    const system = input.systemEnv ?? this.systemEnv;

    for (const key of SYSTEM_KEYS) {
      const value = system[key];
      if (value !== undefined) {
        validateEntry(key, value, 'system');
        result[key] = value;
      }
    }

    this.mergeApplicationEnvironment(result, input.applicationEnv);
    this.mergeTrustedEnvironment(result, input.runtimeEnv, 'runtime');
    this.mergeTrustedEnvironment(result, input.injectionEnv, 'injection');
    return result;
  }

  private mergeApplicationEnvironment(
    target: NodeJS.ProcessEnv, source?: Readonly<Record<string, string>>,
  ): void {
    for (const [key, value] of Object.entries(source ?? {})) {
      validateEntry(key, value, 'application');
      assertAllowedApplicationKey(key);
      target[key] = value;
    }
  }

  private mergeTrustedEnvironment(
    target: NodeJS.ProcessEnv,
    source: Readonly<Record<string, string>> | undefined,
    label: string,
  ): void {
    for (const [key, value] of Object.entries(source ?? {})) {
      validateEntry(key, value, label);
      // A runtime spec must not accidentally turn on Node's CLI preload or loaders.
      if (['NODE_OPTIONS', 'NODE_PATH'].includes(key.toUpperCase())) {
        throw new Error(`Forbidden ${label} environment variable: ${key}`);
      }
      target[key] = value;
    }
  }
}
